theorem T (n : Nat) : n / 3 * 3 ≤ n := 
  by {
    induction n with
    | zero => simp
    | succ n_ih => 
      have : (n_ih + 1) / 3 * 3 ≤ n_ih + 1 := 
        match (n_ih + 1) / 3 with
        | 0 => by simp
        | k + 1 => by 
          { have h : (k + 1) * 3 ≤ n_ih + 1 := Nat.div_le n_ih 3; 
            have h2 : (k + 1) * 3 = 3 * k + 3 := by ring; 
            simp at h; simp at h2; 
            have h3 : 3 * k + 3 ≤ n_ih + 1 := by assumption; 
            simp at h3;
            linarith }
      simp at this; assumption
  }
```

